using System.Collections.Generic;
using System.IO;

namespace Ros.Config
{
    public partial class ConfigManager
    {
        public Dictionary<int, assistant_expression> assistant_expressionData;
        public assistant_expression Getassistant_expressionConfig(int key)
        {
            return ConfigBinary.Require(assistant_expressionData, key, "assistant_expression");
        }
        private void Loadassistant_expressionConfig()
        {
            using (BinaryReader r = ConfigBinary.Open("assistant_expression"))
            {
                int count = r.ReadInt32();
                assistant_expressionData = new Dictionary<int, assistant_expression>(count);
                for (int i = 0; i < count; i++)
                {
                    assistant_expression row;
                    row.key = r.ReadInt32();
                    row.trigger = r.ReadInt32();
                    row.clipId = r.ReadInt32();
                    row.frameDuration = r.ReadSingle();
                    byte has3 = r.ReadByte();
                    row.weight = has3 == 1 ? (int?)(r.ReadInt32()) : null;
                    row.text = ConfigBinary.ReadString(r);
                    row.image = r.ReadInt32();
                    assistant_expressionData.Add(row.key, row);
                }
            }
        }
    }
    public struct assistant_expression
    {
        public int key;  // 主键
        public int trigger;  // 触发事件：0：进入游戏；1：待机动画；2：按钮，3：待机
        public int clipId;  // 动画编号
        public float frameDuration;  // 持续时间（仅同动画最后一个片段使用）
        public int? weight;  // 随机权重
        public string text;  // 文本
        public int image;  // 图片：0：关机；1：正常；2：睡眠；3：眨眼；4：激动；5：微笑；6：紧张；7：惊讶；8：苦力怕；9：五角星
    }
